ight: 3.5rem;\n      line-height: 3.5rem;\n      border-color: #ccc;\n      font-size: 1.2rem;\n      color: #2c2c2c;\n      margin-bottom: 10px; }\n      .page-form .input-field input[type=text][readonly=\"readonly\"] {\n        border-bottom: 1px solid #ccc; }\n        .page-form .input-field input[type=text][readonly=\"readonly\"] + label {\n          color: #808080; }\n      .page-form .input-field input[type=text]:focus:not([readonly]) {\n        border-color: #549cba; }\n        .page-form .input-field input[type=text]:focus:not([readonly]) + label {\n          color: #549cba; }\n    .page-form .input-field ::-webkit-input-placeholder {\n      /* Chrome/Opera/Safari */\n      color: #2c2c2c; }\n    .page-form .input-field .icon-calendar {\n      position: absolute;\n      right: 15px;\n      top: 10px;\n      font-size: 16px;\n      color: #4d6273; }\n  .page-form .dropdown-content {\n    margin-top: 5px;\n    max-height: 400px; }\n  .page-form .dropdown-content li > a, .page-form .dropdown-content li > span {\n    font-size: 1.2rem;\n    color: #2c2c2c; }\n  .page-form .select-wrapper {\n    /*span.caret {\r\n            color: $blue-light;\r\n        }*/ }\n    .page-form .select-wrapper input.select-dropdown {\n      height: 3.5rem;\n      line-height: 3.5rem;\n      border-color: #ccc;\n      font-size: 1.2rem;\n      color: #2c2c2c;\n      margin-bottom: 10px; }\n    .page-form .select-wrapper span.caret {\n      font-family: 'icomoon' !important;\n      color: transparent; }\n      .page-form .select-wrapper span.caret:before {\n        content: \"\\e916\";\n        color: #4d6273;\n        font-size: 18px;\n        position: absolute;\n        top: -7px;\n        right: -5px; }\n\n.table-title {\n  background: #8aa4b8;\n  padding: 4px 15px;\n  color: #fff;\n  text-transform: uppercase; }\n\n.panel-heading {\n  background: #4C6375;\n  border-radius: 0;\n  padding: 0; }\n  .panel-heading .panel-title {\n    color: #fff;\n    padding: 5px 15px;\n    font-s