ctive {\n    text-decoration: none; }\n\n.table > thead > tr > th {\n  vertical-align: middle;\n  text-align: center;\n  background: #d1dae1;\n  border: 1px solid #ffffff;\n  color: #314453;\n  font-weight: 500;\n  padding: 2px 5px;\n  border-radius: 0; }\n  .table > thead > tr > th:first-child {\n    border-left-color: #d1dae1 !important; }\n  .table > thead > tr > th:last-child {\n    border-right-color: #d1dae1 !important; }\n\n.table > thead > tr:nth-child(2) th:last-child {\n  border-right-color: #fff !important; }\n\n.table > thead:first-child > tr:first-child > th {\n  border: 1px solid #ffffff; }\n\n.table > tbody tr td {\n  border: 1px solid #d6d6d6;\n  color: #404040;\n  padding: 2px 5px;\n  background: #ededed; }\n\n.table > tbody tr:nth-child(odd) td {\n  background: #fff; }\n\n.table > tbody tr:hover td {\n  background: #fcf4df; }\n\n.table > tbody tr.total td {\n  background: #ffb391; }\n\n.table > tbody tr.highlight td {\n  background: #f7dbb6;\n  font-weight: bold; }\n\n.page-results {\n  margin: 1.5rem 1.5rem 0; }\n\n.table-title {\n  background: #8aa4b8;\n  padding: 4px 15px;\n  color: #fff;\n  text-transform: uppercase; }\n\n.panel-heading {\n  background: #4C6375;\n  border-radius: 0;\n  padding: 0; }\n  .panel-heading .panel-title {\n    color: #fff;\n    padding: 5px 15px;\n    font-size: 13px; }\n    .panel-heading .panel-title .icon-arrow {\n      margin: 0;\n      font-size: 13px;\n      transform: rotate(-90deg);\n      transition: 0.3s ease all; }\n    .panel-heading .panel-title:hover, .panel-heading .panel-title:active, .panel-heading .panel-title:focus {\n      color: #fff; }\n  .panel-heading + .panel-collapse > .panel-body {\n    border-top: none !important; }\n  .panel-heading.active .panel-title .icon-arrow {\n    transform: rotate(0); }\n\n\n\n/** WEBPACK FOOTER **\n ** webpack:///www/css/source/scss/layout/content.scss\n **/",".page-title .title {\n  font-size: 16px;\n  color: #4060a4;\n  text-transform: uppercase;\n  margin: 0;\n